import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if any(k in l for k in ['!Sample_title','characteristics','treatment','!Series_summary','!Series_overall','growth_protocol','!Series_title','source_name']):
            print(l[:1500].strip())

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if any(k in l for k in ['!Sample_title','characteristics','treatment','!Series_summary','!Series_overall','growth_protocol','source_name','extract_protocol']):
            p=l.strip().split('\t'); u=list(dict.fromkeys(p[1:]))
            print(p[0], u[:40] if 'title' in p[0] else [x[:600] for x in u[:6]])

